return UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).Where(r=>r.name=="Sprout"||r.name=="Plate").Select(r=>new{name=r.name,position=r.transform.position.ToString(),parent=r.transform.parent?.name,materials=r.sharedMaterials.Where(m=>m!=null).Select(m=>new{name=m.name,queue=m.renderQueue,path=UnityEditor.AssetDatabase.GetAssetPath(m),surface=m.HasProperty("_Surface")?m.GetFloat("_Surface"):-1,alpha=m.HasProperty("_BaseColor")?m.GetColor("_BaseColor").a:1}).ToArray()}).ToArray();
